// Event Bus Contract
export interface IEventBus {
  publish(event: string, payload: unknown): void;
  subscribe(event: string, callback: (payload: unknown) => void): void;
}

// Event payloads
export interface TaskAssignedPayload {
  taskId: string;
  taskTitle: string;
  assigneeId: string;
}

export interface TaskStatusChangedPayload {
  taskId: string;
  taskTitle: string;
  assigneeId: string | null;
  oldStatus: TaskStatus;
  newStatus: TaskStatus;
}

export interface CommentAddedPayload {
  commentId: string;
  taskId: string;
  taskTitle: string;
  authorId: string;
  authorName: string;
}

export type TaskStatus = "todo" | "in-progress" | "done";

// Event Bus Implementation
export class EventBus implements IEventBus {
  private subscribers: Map<string, ((payload: unknown) => void)[]> = new Map();

  publish(event: string, payload: unknown): void {
    const callbacks = this.subscribers.get(event);
    if (callbacks) {
      callbacks.forEach((callback) => {
        try {
          callback(payload);
        } catch (error) {
          console.error(`Error in subscriber for event "${event}":`, error);
        }
      });
    }
  }

  subscribe(event: string, callback: (payload: unknown) => void): void {
    if (!this.subscribers.has(event)) {
      this.subscribers.set(event, []);
    }
    this.subscribers.get(event)!.push(callback);
  }
}

// ============================================================
// Data Models
// ============================================================

export interface User {
  id: string;
  name: string;
  email: string;
}

export interface Project {
  id: string;
  name: string;
  description: string;
  memberIds: string[];
}

export type TaskStatus = "todo" | "in-progress" | "done";

export interface Task {
  id: string;
  title: string;
  description: string;
  status: TaskStatus;
  assigneeId: string | null;
  projectId: string;
}

export interface Comment {
  id: string;
  taskId: string;
  authorId: string;
  body: string;
  createdAt: string; // ISO 8601
}

export interface Notification {
  id: string;
  userId: string;
  message: string;
  read: boolean;
  createdAt: string; // ISO 8601
}

// ============================================================
// Service Contracts
// ============================================================

export interface IUserService {
  create(input: { name: string; email: string }): User;
  getById(id: string): User;
  getAll(): User[];
  update(id: string, input: Partial<{ name: string; email: string }>): User;
  delete(id: string): void;
}

export interface IProjectService {
  create(input: { name: string; description: string }): Project;
  getById(id: string): Project;
  getAll(): Project[];
  update(id: string, input: Partial<{ name: string; description: string }>): Project;
  delete(id: string): void;
  addMember(projectId: string, userId: string): Project;
  removeMember(projectId: string, userId: string): Project;
}

export interface ITaskService {
  create(input: { title: string; description: string; projectId: string }): Task;
  getById(id: string): Task;
  getByProject(projectId: string): Task[];
  update(id: string, input: Partial<{ title: string; description: string }>): Task;
  delete(id: string): void;
  assign(taskId: string, assigneeId: string): Task;
  changeStatus(taskId: string, newStatus: TaskStatus): Task;
}

export interface ICommentService {
  create(input: { taskId: string; authorId: string; body: string }): Comment;
  getById(id: string): Comment;
  getByTask(taskId: string): Comment[];
  delete(id: string): void;
}

export interface INotificationService {
  getByUser(userId: string): Notification[];
  markAsRead(notificationId: string): Notification;
}

import { User, IUserService } from "../types";
import { randomBytes } from "crypto";

export class UserService implements IUserService {
  private users: Map<string, User> = new Map();

  private generateId(): string {
    return randomBytes(8).toString("hex");
  }

  create(input: { name: string; email: string }): User {
    const user: User = {
      id: this.generateId(),
      name: input.name,
      email: input.email,
    };
    this.users.set(user.id, user);
    return user;
  }

  getById(id: string): User {
    const user = this.users.get(id);
    if (!user) {
      throw new Error(`User not found: ${id}`);
    }
    return user;
  }

  getAll(): User[] {
    return Array.from(this.users.values());
  }

  update(id: string, input: Partial<{ name: string; email: string }>): User {
    const user = this.getById(id);
    if (input.name !== undefined) {
      user.name = input.name;
    }
    if (input.email !== undefined) {
      user.email = input.email;
    }
    return user;
  }

  delete(id: string): void {
    const user = this.getById(id);
    this.users.delete(id);
  }
}

import { Project, IProjectService } from "../types";
import { randomBytes } from "crypto";

export class ProjectService implements IProjectService {
  private projects: Map<string, Project> = new Map();

  private generateId(): string {
    return randomBytes(8).toString("hex");
  }

  create(input: { name: string; description: string }): Project {
    const project: Project = {
      id: this.generateId(),
      name: input.name,
      description: input.description,
      memberIds: [],
    };
    this.projects.set(project.id, project);
    return project;
  }

  getById(id: string): Project {
    const project = this.projects.get(id);
    if (!project) {
      throw new Error(`Project not found: ${id}`);
    }
    return project;
  }

  getAll(): Project[] {
    return Array.from(this.projects.values());
  }

  update(
    id: string,
    input: Partial<{ name: string; description: string }>
  ): Project {
    const project = this.getById(id);
    if (input.name !== undefined) {
      project.name = input.name;
    }
    if (input.description !== undefined) {
      project.description = input.description;
    }
    return project;
  }

  delete(id: string): void {
    const project = this.getById(id);
    this.projects.delete(id);
  }

  addMember(projectId: string, userId: string): Project {
    const project = this.getById(projectId);
    if (!project.memberIds.includes(userId)) {
      project.memberIds.push(userId);
    }
    return project;
  }

  removeMember(projectId: string, userId: string): Project {
    const project = this.getById(projectId);
    project.memberIds = project.memberIds.filter((id) => id !== userId);
    return project;
  }
}

import { Task, TaskStatus, ITaskService } from "../types";
import { IEventBus, TaskAssignedPayload, TaskStatusChangedPayload } from "../event-bus";
import { randomBytes } from "crypto";

export class TaskService implements ITaskService {
  private tasks: Map<string, Task> = new Map();

  constructor(private eventBus: IEventBus) {}

  private generateId(): string {
    return randomBytes(8).toString("hex");
  }

  create(input: {
    title: string;
    description: string;
    projectId: string;
  }): Task {
    const task: Task = {
      id: this.generateId(),
      title: input.title,
      description: input.description,
      status: "todo",
      assigneeId: null,
      projectId: input.projectId,
    };
    this.tasks.set(task.id, task);
    return task;
  }

  getById(id: string): Task {
    const task = this.tasks.get(id);
    if (!task) {
      throw new Error(`Task not found: ${id}`);
    }
    return task;
  }

  getByProject(projectId: string): Task[] {
    return Array.from(this.tasks.values()).filter(
      (task) => task.projectId === projectId
    );
  }

  update(id: string, input: Partial<{ title: string; description: string }>): Task {
    const task = this.getById(id);
    if (input.title !== undefined) {
      task.title = input.title;
    }
    if (input.description !== undefined) {
      task.description = input.description;
    }
    return task;
  }

  delete(id: string): void {
    const task = this.getById(id);
    this.tasks.delete(id);
  }

  assign(taskId: string, assigneeId: string): Task {
    const task = this.getById(taskId);
    task.assigneeId = assigneeId;

    // Publish task.assigned event
    const payload: TaskAssignedPayload = {
      taskId: task.id,
      taskTitle: task.title,
      assigneeId: assigneeId,
    };
    this.eventBus.publish("task.assigned", payload);

    return task;
  }

  changeStatus(taskId: string, newStatus: TaskStatus): Task {
    const task = this.getById(taskId);
    const oldStatus = task.status;

    // RULE 4: Forward-only status transitions
    // todo → in-progress → done
    const validTransitions: Record<TaskStatus, TaskStatus[]> = {
      todo: ["in-progress"],
      "in-progress": ["done"],
      done: [],
    };

    if (!validTransitions[oldStatus].includes(newStatus)) {
      throw new Error(
        `Invalid status transition: ${oldStatus} → ${newStatus}. ` +
          `Valid transitions are: ${validTransitions[oldStatus].join(", ") || "none"}`
      );
    }

    task.status = newStatus;

    // Publish task.statusChanged event
    const payload: TaskStatusChangedPayload = {
      taskId: task.id,
      taskTitle: task.title,
      assigneeId: task.assigneeId,
      oldStatus,
      newStatus,
    };
    this.eventBus.publish("task.statusChanged", payload);

    return task;
  }
}

import { Comment, ICommentService } from "../types";
import { IEventBus, CommentAddedPayload } from "../event-bus";
import { randomBytes } from "crypto";

export class CommentService implements ICommentService {
  private comments: Map<string, Comment> = new Map();

  constructor(
    private eventBus: IEventBus,
    private getUserName: (userId: string) => string
  ) {}

  private generateId(): string {
    return randomBytes(8).toString("hex");
  }

  create(input: { taskId: string; authorId: string; body: string }): Comment {
    const comment: Comment = {
      id: this.generateId(),
      taskId: input.taskId,
      authorId: input.authorId,
      body: input.body,
      createdAt: new Date().toISOString(),
    };
    this.comments.set(comment.id, comment);

    // Publish comment.added event
    const authorName = this.getUserName(input.authorId);
    const payload: CommentAddedPayload = {
      commentId: comment.id,
      taskId: input.taskId,
      taskTitle: "", // Will be filled by router/consumer
      authorId: input.authorId,
      authorName,
    };
    this.eventBus.publish("comment.added", payload);

    return comment;
  }

  getById(id: string): Comment {
    const comment = this.comments.get(id);
    if (!comment) {
      throw new Error(`Comment not found: ${id}`);
    }
    return comment;
  }

  getByTask(taskId: string): Comment[] {
    return Array.from(this.comments.values()).filter(
      (comment) => comment.taskId === taskId
    );
  }

  delete(id: string): void {
    const comment = this.getById(id);
    this.comments.delete(id);
  }
}

import { Notification, INotificationService } from "../types";
import { randomBytes } from "crypto";

export class NotificationService implements INotificationService {
  private notifications: Map<string, Notification> = new Map();

  private generateId(): string {
    return randomBytes(8).toString("hex");
  }

  createNotification(userId: string, message: string): Notification {
    const notification: Notification = {
      id: this.generateId(),
      userId,
      message,
      read: false,
      createdAt: new Date().toISOString(),
    };
    this.notifications.set(notification.id, notification);
    return notification;
  }

  getByUser(userId: string): Notification[] {
    return Array.from(this.notifications.values()).filter(
      (notification) => notification.userId === userId
    );
  }

  markAsRead(notificationId: string): Notification {
    const notification = this.notifications.get(notificationId);
    if (!notification) {
      throw new Error(`Notification not found: ${notificationId}`);
    }
    notification.read = true;
    return notification;
  }
}

import { IncomingMessage, ServerResponse } from "http";
import { URL } from "url";
import { UserService } from "./services/user-service";
import { ProjectService } from "./services/project-service";
import { TaskService } from "./services/task-service";
import { CommentService } from "./services/comment-service";
import { NotificationService } from "./services/notification-service";

export class Router {
  constructor(
    private userService: UserService,
    private projectService: ProjectService,
    private taskService: TaskService,
    private commentService: CommentService,
    private notificationService: NotificationService
  ) {}

  async handleRequest(
    req: IncomingMessage,
    res: ServerResponse
  ): Promise<void> {
    const url = new URL(req.url || "", `http://${req.headers.host || "localhost"}`);
    const pathname = url.pathname;
    const method = req.method || "GET";
    const searchParams = url.searchParams;

    try {
      // User routes
      if (pathname === "/users" && method === "GET") {
        const users = this.userService.getAll();
        return this.sendJson(res, 200, users);
      }

      if (pathname === "/users" && method === "POST") {
        const body = await this.parseBody(req);
        const user = this.userService.create(body);
        return this.sendJson(res, 201, user);
      }

      const userMatch = pathname.match(/^\/users\/([^/]+)$/);
      if (userMatch && method === "GET") {
        const id = userMatch[1];
        const user = this.userService.getById(id);
        return this.sendJson(res, 200, user);
      }

      if (userMatch && method === "PUT") {
        const id = userMatch[1];
        const body = await this.parseBody(req);
        const user = this.userService.update(id, body);
        return this.sendJson(res, 200, user);
      }

      if (userMatch && method === "DELETE") {
        const id = userMatch[1];
        this.userService.delete(id);
        return this.sendJson(res, 204, null);
      }

      // Project routes
      if (pathname === "/projects" && method === "GET") {
        const projects = this.projectService.getAll();
        return this.sendJson(res, 200, projects);
      }

      if (pathname === "/projects" && method === "POST") {
        const body = await this.parseBody(req);
        const project = this.projectService.create(body);
        return this.sendJson(res, 201, project);
      }

      const projectMatch = pathname.match(/^\/projects\/([^/]+)$/);
      if (projectMatch && method === "GET") {
        const id = projectMatch[1];
        const project = this.projectService.getById(id);
        return this.sendJson(res, 200, project);
      }

      if (projectMatch && method === "PUT") {
        const id = projectMatch[1];
        const body = await this.parseBody(req);
        const project = this.projectService.update(id, body);
        return this.sendJson(res, 200, project);
      }

      if (projectMatch && method === "DELETE") {
        const id = projectMatch[1];
        this.projectService.delete(id);
        return this.sendJson(res, 204, null);
      }

      const projectMemberMatch = pathname.match(/^\/projects\/([^/]+)\/members$/);
      if (projectMemberMatch && method === "POST") {
        const projectId = projectMemberMatch[1];
        const body = await this.parseBody(req);
        const project = this.projectService.addMember(projectId, body.userId);
        return this.sendJson(res, 200, project);
      }

      if (projectMemberMatch && method === "DELETE") {
        const projectId = projectMemberMatch[1];
        const body = await this.parseBody(req);
        const project = this.projectService.removeMember(projectId, body.userId);
        return this.sendJson(res, 200, project);
      }

      // Task routes
      if (pathname === "/tasks" && method === "GET") {
        const projectId = searchParams.get("projectId");
        if (!projectId) {
          return this.sendJson(res, 400, { error: "projectId query parameter required" });
        }
        const tasks = this.taskService.getByProject(projectId);
        return this.sendJson(res, 200, tasks);
      }

      if (pathname === "/tasks" && method === "POST") {
        const body = await this.parseBody(req);
        const task = this.taskService.create(body);
        return this.sendJson(res, 201, task);
      }

      const taskMatch = pathname.match(/^\/tasks\/([^/]+)$/);
      if (taskMatch && method === "GET") {
        const id = taskMatch[1];
        const task = this.taskService.getById(id);
        return this.sendJson(res, 200, task);
      }

      if (taskMatch && method === "PUT") {
        const id = taskMatch[1];
        const body = await this.parseBody(req);
        const task = this.taskService.update(id, body);
        return this.sendJson(res, 200, task);
      }

      if (taskMatch && method === "DELETE") {
        const id = taskMatch[1];
        this.taskService.delete(id);
        return this.sendJson(res, 204, null);
      }

      const taskStatusMatch = pathname.match(/^\/tasks\/([^/]+)\/status$/);
      if (taskStatusMatch && method === "PUT") {
        const taskId = taskStatusMatch[1];
        const body = await this.parseBody(req);
        const task = this.taskService.changeStatus(taskId, body.status);
        return this.sendJson(res, 200, task);
      }

      const taskAssignMatch = pathname.match(/^\/tasks\/([^/]+)\/assign$/);
      if (taskAssignMatch && method === "PUT") {
        const taskId = taskAssignMatch[1];
        const body = await this.parseBody(req);
        const task = this.taskService.assign(taskId, body.assigneeId);
        return this.sendJson(res, 200, task);
      }

      // Comment routes
      if (pathname === "/comments" && method === "GET") {
        const taskId = searchParams.get("taskId");
        if (!taskId) {
          return this.sendJson(res, 400, { error: "taskId query parameter required" });
        }
        const comments = this.commentService.getByTask(taskId);
        return this.sendJson(res, 200, comments);
      }

      if (pathname === "/comments" && method === "POST") {
        const body = await this.parseBody(req);
        const comment = this.commentService.create(body);
        return this.sendJson(res, 201, comment);
      }

      const commentMatch = pathname.match(/^\/comments\/([^/]+)$/);
      if (commentMatch && method === "GET") {
        const id = commentMatch[1];
        const comment = this.commentService.getById(id);
        return this.sendJson(res, 200, comment);
      }

      if (commentMatch && method === "DELETE") {
        const id = commentMatch[1];
        this.commentService.delete(id);
        return this.sendJson(res, 204, null);
      }

      // Notification routes
      if (pathname === "/notifications" && method === "GET") {
        const userId = searchParams.get("userId");
        if (!userId) {
          return this.sendJson(res, 400, { error: "userId query parameter required" });
        }
        const notifications = this.notificationService.getByUser(userId);
        return this.sendJson(res, 200, notifications);
      }

      const notificationReadMatch = pathname.match(/^\/notifications\/([^/]+)\/read$/);
      if (notificationReadMatch && method === "PUT") {
        const notificationId = notificationReadMatch[1];
        const notification = this.notificationService.markAsRead(notificationId);
        return this.sendJson(res, 200, notification);
      }

      // 404
      return this.sendJson(res, 404, { error: "Not found" });
    } catch (error) {
      const message = error instanceof Error ? error.message : "Internal server error";
      return this.sendJson(res, 500, { error: message });
    }
  }

  private async parseBody(req: IncomingMessage): Promise<unknown> {
    return new Promise((resolve, reject) => {
      let data = "";
      req.on("data", (chunk) => {
        data += chunk.toString();
      });
      req.on("end", () => {
        try {
          resolve(data ? JSON.parse(data) : {});
        } catch (error) {
          reject(new Error("Invalid JSON in request body"));
        }
      });
      req.on("error", reject);
    });
  }

  private sendJson(res: ServerResponse, statusCode: number, data: unknown): void {
    res.writeHead(statusCode, { "Content-Type": "application/json" });
    if (statusCode === 204) {
      res.end();
    } else {
      res.end(JSON.stringify(data, null, 2));
    }
  }
}

import { createServer } from "http";
import { EventBus } from "./event-bus";
import { UserService } from "./services/user-service";
import { ProjectService } from "./services/project-service";
import { TaskService } from "./services/task-service";
import { CommentService } from "./services/comment-service";
import { NotificationService } from "./services/notification-service";
import { Router } from "./router";
import { TaskAssignedPayload, TaskStatusChangedPayload, CommentAddedPayload } from "./event-bus";

export class Application {
  private eventBus: EventBus;
  private userService: UserService;
  private projectService: ProjectService;
  private taskService: TaskService;
  private commentService: CommentService;
  private notificationService: NotificationService;
  private router: Router;

  constructor() {
    // Initialize Event Bus
    this.eventBus = new EventBus();

    // Initialize Services
    this.userService = new UserService();
    this.projectService = new ProjectService();
    this.notificationService = new NotificationService();

    // Services that depend on EventBus
    this.taskService = new TaskService(this.eventBus);

    const getUserName = (userId: string): string => {
      try {
        return this.userService.getById(userId).name;
      } catch {
        return "Unknown User";
      }
    };

    const getTaskById = (taskId: string) => {
      try {
        return this.taskService.getById(taskId);
      } catch {
        return null;
      }
    };

    this.commentService = new CommentService(this.eventBus, getUserName);

    // Initialize Router
    this.router = new Router(
      this.userService,
      this.projectService,
      this.taskService,
      this.commentService,
      this.notificationService
    );

    // Wire up event subscriptions
    this.setupEventSubscriptions();
  }

  private setupEventSubscriptions(): void {
    // NotificationService subscribes to task.assigned
    this.eventBus.subscribe("task.assigned", (payload: unknown) => {
      const p = payload as TaskAssignedPayload;
      this.notificationService.createNotification(
        p.assigneeId,
        `Task '${p.taskTitle}' assigned to you`
      );
    });

    // NotificationService subscribes to task.statusChanged
    this.eventBus.subscribe("task.statusChanged", (payload: unknown) => {
      const p = payload as TaskStatusChangedPayload;
      if (p.assigneeId) {
        this.notificationService.createNotification(
          p.assigneeId,
          `Task '${p.taskTitle}' status changed to ${p.newStatus}`
        );
      }
    });

    // NotificationService subscribes to comment.added
    this.eventBus.subscribe("comment.added", (payload: unknown) => {
      const p = payload as CommentAddedPayload;
      const task = this.getTaskById(p.taskId);
      if (task && task.assigneeId && task.assigneeId !== p.authorId) {
        this.notificationService.createNotification(
          task.assigneeId,
          `${p.authorName} commented on task '${task.title}'`
        );
      }
    });
  }

  private getTaskById(taskId: string) {
    try {
      return this.taskService.getById(taskId);
    } catch {
      return null;
    }
  }

  start(port: number = 3000): void {
    const server = createServer((req, res) => {
      this.router.handleRequest(req, res).catch((error) => {
        console.error("Unhandled error in request handler:", error);
        res.writeHead(500, { "Content-Type": "application/json" });
        res.end(JSON.stringify({ error: "Internal server error" }));
      });
    });

    server.listen(port, () => {
      console.log(`Task Management API listening on http://localhost:${port}`);
    });
  }

  // Expose services for testing/demo
  getServices() {
    return {
      userService: this.userService,
      projectService: this.projectService,
      taskService: this.taskService,
      commentService: this.commentService,
      notificationService: this.notificationService,
    };
  }
}

// Start the server if this is the main module
if (require.main === module) {
  const app = new Application();
  app.start(3000);
}

export default Application;

import Application from "./main";

async function sleep(ms: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

async function makeRequest(
  method: string,
  path: string,
  body?: unknown
): Promise<unknown> {
  return new Promise((resolve, reject) => {
    const url = new URL(path, "http://localhost:3000");
    const options = {
      hostname: "localhost",
      port: 3000,
      path: url.pathname + url.search,
      method: method,
      headers: {
        "Content-Type": "application/json",
      },
    };

    const req = require("http").request(options, (res: any) => {
      let data = "";
      res.on("data", (chunk: Buffer) => {
        data += chunk.toString();
      });
      res.on("end", () => {
        try {
          resolve(JSON.parse(data));
        } catch {
          resolve(data);
        }
      });
    });

    req.on("error", reject);

    if (body) {
      req.write(JSON.stringify(body));
    }
    req.end();
  });
}

async function runDemo(): Promise<void> {
  console.log("=== Task Management API Demo ===\n");

  // Start server
  const app = new Application();
  app.start(3000);

  // Wait for server to start
